import{readFile,writeFile}from'node:fs/promises';import{browserTool}from'./mcp-call.mjs';const report=JSON.parse(await readFile('analysis/seven-smart-2026-10-20/outputs.json'));const rows=[];for(const s of report.outputs){const begin=Date.now();const active=await browserTool('scene.activate',{sceneId:s.sceneId});const openMs=Date.now()-begin;if(active.id!==s.sceneId)throw Error('Wrong scene');await browserTool('playback.control',{operation:'seek',timeSeconds:0});await browserTool('playback.control',{operation:'play'});await new Promise(r=>setTimeout(r,1300));const end=await browserTool('playback.control',{operation:'pause'});const seconds=end.currentTimeSeconds??end.currentTime/120000;if(!(seconds>.5))throw Error(`Playback did not advance: ${JSON.stringify(end)}`);rows.push({sceneId:s.sceneId,openMs,playedSeconds:seconds,playbackAdvanced:true,muted:end.muted});console.log(rows.at(-1));}
const state=await browserTool('app.get_state');await writeFile('.local/seven-smart-2026-10-20/playback-metrics.json',JSON.stringify({rows,state},null,2));await writeFile('analysis/seven-smart-2026-10-20/playback.json',JSON.stringify({passed:true,outputs:rows.map(({openMs,playedSeconds,...r})=>r),projectSceneCount:state.scenes.length,diagnostics:state.diagnostics,scope:'Live playback advances on every saved scene; decoded source signals checked separately. Not exhaustive listening or export.'},null,2));
